f=$(readlink -f /etc/nginx/sites-enabled/* | head -1); ls -la /etc/nginx/sites-enabled/; cp $f /root/nginx-site.bak
python3 - "$f" <<'E'
import sys
p=sys.argv[1]; s=open(p).read()
block='''    # No script execution from the upload and cache folders; no backup or dot files.
    location ~* ^/(wp-content/uploads|wp-content/cache|assets-cache)/.*\\.(php\\d?|phtml|phar|pht)(/|$) {
        deny all;
    }
    location ~* \\.(bak|orig|old|swp|sql|log)$ {
        deny all;
    }

    location ~ \\.php$ {'''
if 'No script execution' not in s:
    s=s.replace('    location ~ \\.php$ {',block,1)
    open(p,'w').write(s)
E
nginx -t && service nginx reload; sleep 1
